// Cloud mode uses a readable CSRF cookie and sends its token on every same-origin write request.
// On the local desktop profile the CSRF endpoint is absent, so this wrapper remains a no-op.
const __rawFetch = window.fetch.bind(window);
window.fetch = function(input, init = {}) {
  let url = null;
  try { url = new URL(typeof input === 'string' ? input : input.url, window.location.href); } catch (_) {}
  const method = String(init.method || (input instanceof Request ? input.method : 'GET')).toUpperCase();
  if (url && url.origin === window.location.origin && !['GET','HEAD','OPTIONS','TRACE'].includes(method)) {
    const match = document.cookie.match(/(?:^|;\s*)XSRF-TOKEN=([^;]+)/);
    if (match) {
      const headers = new Headers(input instanceof Request ? input.headers : undefined);
      new Headers(init.headers || {}).forEach((value, key) => headers.set(key, value));
      try { headers.set('X-XSRF-TOKEN', decodeURIComponent(match[1])); } catch (_) { headers.set('X-XSRF-TOKEN', match[1]); }
      init = { ...init, headers };
    }
  }
  return __rawFetch(input, init);
};
async function ensureCsrfToken() {
  try { await fetch('/api/auth/csrf?_=' + Date.now(), { credentials: 'same-origin', cache: 'no-store' }); } catch (_) {}
}
let syncRevision = null, syncTimer = null, syncCheckBusy = false;
async function readSyncRevision() {
  try {
    const r = await fetch('/api/sync/status?_=' + Date.now(), { credentials: 'same-origin', cache: 'no-store' });
    if (!r.ok) return null;
    const data = await r.json();
    return Number(data.revision);
  } catch (_) { return null; }
}
function startSyncPolling() {
  if (syncTimer !== null) return;
  syncTimer = setInterval(checkSyncRevision, 5000);
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') checkSyncRevision(); });
}
async function checkSyncRevision() {
  if (syncCheckBusy || document.visibilityState !== 'visible' || !$('auth')?.classList.contains('hidden')) return;
  syncCheckBusy = true;
  try {
    const latest = await readSyncRevision();
    if (latest === null) return;
    if (syncRevision === null) { syncRevision = latest; return; }
    if (latest === syncRevision) return;
    const active = document.activeElement;
    const editing = active && ['INPUT','TEXTAREA','SELECT'].includes(active.tagName);
    if ($('modal')?.classList.contains('open') || editing) return;
    syncRevision = latest;
    await loadAll();
    toast('Đã đồng bộ dữ liệu mới từ máy chủ.');
  } finally { syncCheckBusy = false; }
}
