function toast(msg,bad=false,actionLabel=null,actionFn=null,duration=2800){const t=$('toast');t.innerHTML='';const m=document.createElement('span');m.textContent=msg;t.appendChild(m);if(actionLabel&&typeof actionFn==='function'){const b=document.createElement('button');b.type='button';b.className='toast-action';b.textContent=actionLabel;b.onclick=async()=>{clearTimeout(window.__tt);t.className='toast';try{await actionFn()}catch(e){toast(e.message||'Không hoàn tác được',true)}};t.appendChild(b)}t.className='toast show'+(bad?' bad':'');clearTimeout(window.__tt);window.__tt=setTimeout(()=>t.className='toast',duration)}
async function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','Cache-Control':'no-cache',...(opt.headers||{})},...opt});if(r.status===401){showAuth('Phiên đã khóa. Nhập mật khẩu để mở lại.');throw new Error('Cần đăng nhập lại')}if(!r.ok){let m='Có lỗi xảy ra';try{m=(await r.json()).message||m}catch{}throw new Error(m)}if(r.status===204)return null;return r.json()}
