async function setupApp(){const a=$('setupPassword').value,b=$('setupPassword2').value;if(a.length<minimumPasswordLength){$('authError').textContent='Mật khẩu cần ít nhất '+minimumPasswordLength+' ký tự.';return}if(a!==b){$('authError').textContent='Hai lần nhập chưa giống nhau.';return}try{const r=await api('/api/auth/setup',{method:'POST',body:JSON.stringify({password:a,setupKey:$('setupKey')?.value||''})});alert('MÃ KHÔI PHỤC MẬT KHẨU\n\n'+r.recoveryCode+'\n\nHãy chụp ảnh hoặc ghi mã này ra giấy và cất riêng. Mã dùng khi quên mật khẩu.');$('auth').classList.add('hidden');await loadAll();toast('Đã mở kho. Bắt đầu bằng cách thêm mặt hàng đầu tiên.');maybeShowLowStockAlert()}catch(e){$('authError').textContent=e.message}}
