async function loadAll(){try{const today=new Date().toISOString().slice(0,10),fresh='_='+Date.now();const [products,tx,expenses,stocktakes,purchases,dashboard,todayReport]=await Promise.all([api('/api/products?'+fresh),api('/api/inventory?'+fresh),api('/api/expenses?'+fresh),api('/api/stocktakes?'+fresh),api('/api/purchases/suggestions?'+fresh),api('/api/reports/dashboard?'+fresh),api('/api/reports/period?period=DAY&date='+today+'&'+fresh)]);state.products=products;state.tx=tx;state.expenses=expenses;state.stocktakes=stocktakes;state.purchases=purchases;state.dashboard=dashboard;state.todayReport=todayReport;if(!state.purchaseSelected.size)purchases.forEach(x=>state.purchaseSelected.add(x.id));if(!state.reportSelected.size)products.filter(p=>['Nguyên liệu / Gia vị','Công cụ / Dụng cụ','Nước / Đồ uống'].includes(p.category)).forEach(p=>state.reportSelected.add(p.id));renderAll();await refreshReportPreview();const revision=await readSyncRevision();if(revision!==null)syncRevision=revision;startSyncPolling()}catch(e){if(e.message!=='Cần đăng nhập lại')toast(e.message,true)}}
function status(p){if(Number(p.quantity)<=0)return['Hết hàng','out'];if(Number(p.quantity)<=Number(p.minStock))return['Sắp hết','low'];return['Còn đủ','ok']}
