function renderDashboard(){const d=state.dashboard;$('sProducts').textContent=d.productTypes??0;$('sUnits').textContent=num.format(d.totalUnits??0);$('sLow').textContent=d.lowStock??0;$('sValue').textContent=money.format(d.stockValue??0);$('firstUse').classList.toggle('hidden',state.products.length>0);$('recentTx').innerHTML=state.tx.length?state.tx.slice(0,5).map(t=>`<div class="tx"><div><small>${new Date(t.createdAt).toLocaleDateString('vi-VN')}</small><br><b>${new Date(t.createdAt).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}</b></div><div><b>${esc(t.productName)}</b><br><small>${t.type==='OUT'?'Xuất hàng':t.type==='OPENING'?'Số tồn ban đầu':t.type==='ADJUST_IN'||t.type==='ADJUST_OUT'?'Điều chỉnh Excel':'Nhập hàng'}${t.note?' · '+esc(t.note):''}</small></div><div class="${t.type==='OUT'||t.type==='ADJUST_OUT'?'qty-out':'qty-in'}">${t.type==='OUT'||t.type==='ADJUST_OUT'?'-':'+'}${num.format(t.quantity)} ${esc(t.unit)}</div></div>`).join(''):'<div class="empty">Chưa có việc nhập hoặc xuất nào.<br>Hôm nay có thể bắt đầu từ các nút lớn phía trên.</div>';const low=state.products.filter(p=>Number(p.quantity)<=Number(p.minStock));$('lowStock').innerHTML=low.length?low.slice(0,6).map(p=>`<div class="tx"><div>⚠️</div><div><b>${esc(p.name)}</b><br><small>Đang còn ${num.format(p.quantity)} ${esc(p.unit)} · nên báo khi còn ${num.format(p.minStock)}</small></div><span class="badge ${status(p)[1]}">${status(p)[0]}</span></div>`).join(''):'<div class="empty">Ổn rồi — chưa có mặt hàng nào cần mua thêm.</div>'}
function renderProducts(){let q=$('productSearch').value.toLowerCase(),f=$('stockFilter').value,c=$('categoryFilter').value;let arr=state.products.filter(p=>(p.name+' '+(p.sku||'')).toLowerCase().includes(q)).filter(p=>c==='all'||(p.category||'Khác')===c).filter(p=>f==='all'||(f==='low'?Number(p.quantity)<=Number(p.minStock):Number(p.quantity)>Number(p.minStock)));$('productRows').innerHTML=arr.length?arr.map(p=>{let st=status(p);return `<tr><td><b>${esc(p.name)}</b>${p.note?`<br><small>${esc(p.note)}</small>`:''}${p.sku?`<br><small>Mã: ${esc(p.sku)}</small>`:''}</td><td>${esc(p.category||'Khác')}</td><td>${esc(p.unit)}${p.packageUnit&&Number(p.unitsPerPackage)>1?`<br><small>1 ${esc(p.packageUnit)} = ${num.format(p.unitsPerPackage)} ${esc(p.unit)}</small>`:''}</td><td class="right"><b>${num.format(p.quantity)}</b>${p.packageUnit&&Number(p.unitsPerPackage)>1?`<br><small>≈ ${num.format(Number(p.quantity)/Number(p.unitsPerPackage))} ${esc(p.packageUnit)}</small>`:''}</td><td class="right">${num.format(p.minStock)}</td><td class="right">${money.format(p.unitPrice)}</td><td><span class="badge ${st[1]}">${st[0]}</span></td><td><div class="row-actions"><button class="btn small" onclick="openProductHistory(${p.id})">📖 Lịch sử</button><button class="btn small" onclick="openStocktake(${p.id})">✅ Kiểm kê</button><button class="btn small" onclick="openOpeningStock(${p.id})">Tồn đầu</button><button class="btn small" onclick="openProduct(${p.id})">Sửa</button><button class="btn small red" onclick="deleteProduct(${p.id})">Xóa</button></div></td></tr>`}).join(''):'<tr><td colspan="8" class="empty">Chưa có mặt hàng nào.<br><div class="row-actions" style="justify-content:center;margin-top:10px"><button class="btn" onclick="openExcelImport()">📄 Nhập từ Excel</button><button class="btn primary" onclick="openProduct()">＋ Thêm mặt hàng</button></div></td></tr>'}
