async function refreshReportPreview(){if(!$('reportDate'))return;if(!$('reportDate').value)$('reportDate').value=new Date().toISOString().slice(0,10);if(!$('movementReportDate').value)$('movementReportDate').value=new Date().toISOString().slice(0,10);const ids=reportSelectedIds(),period=$('reportPeriod').value,date=$('reportDate').value;if(!ids.length){state.reportPreview=null;$('reportPeriodText').textContent='Chưa chọn mặt hàng nào để báo cáo.';$('reportPreview').innerHTML='';return}try{const q=new URLSearchParams({period,date});ids.forEach(id=>q.append('productIds',id));const r=await api('/api/reports/period?'+q.toString());state.reportPreview=r;const from=new Date(r.fromDate+'T00:00:00').toLocaleDateString('vi-VN'),to=new Date(r.toDate+'T00:00:00').toLocaleDateString('vi-VN');$('reportPeriodText').innerHTML=`Báo cáo từ <b>${from}</b>${from!==to?` đến <b>${to}</b>`:''} · đã chọn <b>${r.selectedProducts}</b> mặt hàng.`;$('reportPreview').innerHTML=`<div class="mini-stat"><span>Nhập trong kỳ</span><b>${num.format(r.totalIn)}</b></div><div class="mini-stat"><span>Xuất trong kỳ</span><b>${num.format(r.totalOut)}</b></div><div class="mini-stat"><span>Tồn cuối kỳ</span><b>${num.format(r.totalClosing)}</b></div><div class="mini-stat"><span>Mặt hàng báo cáo</span><b>${r.selectedProducts}</b></div>`}catch(e){toast(e.message,true)}}
async function exportDailyMovement(type){const date=$('movementReportDate').value||new Date().toISOString().slice(0,10);const endpoint=type==='IN'?'/api/reports/daily-inbound-excel':'/api/reports/daily-outbound-excel';try{const r=await fetch(endpoint+'?date='+encodeURIComponent(date),{credentials:'same-origin'});if(r.status===401){showAuth('Phiên đã khóa. Nhập mật khẩu để mở lại.');return}if(!r.ok){let m='Không tạo được file Excel';try{m=(await r.json()).message||m}catch{}throw new Error(m)}const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);const cd=r.headers.get('Content-Disposition')||'';const m=cd.match(/filename="?([^";]+)"?/);a.download=m?m[1]:(type==='IN'?'BANG-NHAP-HANG.xlsx':'PHIEU-XUAT-KHO.xlsx');a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast(type==='IN'?'Đã tạo file nhập hàng theo ngày':'Đã tạo phiếu xuất kho theo ngày')}catch(e){toast(e.message,true)}}
async function exportExcelReport(){const ids=reportSelectedIds();if(!ids.length){toast('Hãy chọn ít nhất một mặt hàng để đưa vào báo cáo.',true);return}const body={period:$('reportPeriod').value,date:$('reportDate').value,productIds:ids};try{const r=await fetch('/api/reports/excel',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(r.status===401){showAuth('Phiên đã khóa. Nhập mật khẩu để mở lại.');return}if(!r.ok){let m='Không tạo được file Excel';try{m=(await r.json()).message||m}catch{}throw new Error(m)}const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);const cd=r.headers.get('Content-Disposition')||'';const m=cd.match(/filename="?([^";]+)"?/);a.download=m?m[1]:'bao-cao-kho.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Đã tạo báo cáo Excel')}catch(e){toast(e.message,true)}}
function openModal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').classList.add('open')}function closeModal(){$('modal').classList.remove('open','history')}
function openProduct(id,afterCreateTxType){let p=id?state.products.find(x=>x.id===id):null;openModal(p?'Sửa mặt hàng':'Thêm mặt hàng mới',`<div class="note" style="margin-bottom:12px">Mặt hàng <b>không cần có sẵn trong file Excel</b>. Bạn có thể đổi <b>Nhóm hàng</b> tại đây; nhóm bạn chọn thủ công sẽ được giữ nguyên khi import Excel sau này. Với nước/bia, nên lưu tồn theo <b>lon/chai</b>.</div><div class="form-grid"><div class="field"><label>Nhóm hàng *</label><select id="pCategory"><option value="Nguyên liệu / Gia vị" ${(p?.category||'Nguyên liệu / Gia vị')==='Nguyên liệu / Gia vị'?'selected':''}>Nguyên liệu / Gia vị</option><option value="Công cụ / Dụng cụ" ${p?.category==='Công cụ / Dụng cụ'?'selected':''}>Công cụ / Dụng cụ</option><option value="Nước / Đồ uống" ${p?.category==='Nước / Đồ uống'?'selected':''}>Nước / Đồ uống</option><option value="Khác" ${p?.category==='Khác'?'selected':''}>Khác</option></select></div><div class="field"><label>Mã hàng</label><input id="pSku" autocomplete="off" value="${esc(p?.sku||'')}" placeholder="Có thể bỏ trống"></div><div class="field full"><label>Tên hàng *</label><input id="pName" autocomplete="off" placeholder="Ví dụ: Pepsi lon 330ml" value="${esc(p?.name||'')}"></div><div class="field"><label>Đơn vị tồn kho *</label><input id="pUnit" list="unitList" placeholder="LON, CHAI, CÁI, KG..." value="${esc(p?.unit||'')}"><datalist id="unitList"><option value="CÁI"><option value="KG"><option value="BỊCH"><option value="GÓI"><option value="CHAI"><option value="LON"><option value="THÙNG"><option value="KÉT"><option value="BAO"><option value="HỘP"><option value="CAN"><option value="CUỘN"><option value="ĐÔI"></datalist><span class="hint">Nước/bia nên chọn LON hoặc CHAI để có thể xuất lẻ.</span></div>${p?'':`<div class="field"><label>Số đang có trong kho</label><input id="pOpening" type="number" inputmode="decimal" min="0" step="0.001" value="0"><span class="hint">Nhập theo đơn vị tồn kho ở bên trái.</span></div>`}<div class="field full"><label>Ghi chú</label><textarea id="pNote" rows="2" placeholder="Có thể bỏ trống">${esc(p?.note||'')}</textarea></div><details class="optional field full" ${p?.packageUnit?'open':''}><summary>Quy đổi thùng / két & thiết lập thêm</summary><div class="form-grid" style="margin-top:10px"><div class="field"><label>Đơn vị đóng gói</label><input id="pPackageUnit" list="packageUnitList" placeholder="Ví dụ: THÙNG hoặc KÉT" value="${esc(p?.packageUnit||'')}"><datalist id="packageUnitList"><option value="THÙNG"><option value="KÉT"><option value="LỐC"><option value="HỘP"><option value="BAO"></datalist></div><div class="field"><label>1 đơn vị đóng gói có bao nhiêu ${esc(p?.unit||'đơn vị lẻ')}</label><input id="pUnitsPerPackage" type="number" inputmode="decimal" min="0" step="0.001" value="${p?.unitsPerPackage??0}" placeholder="Ví dụ: 24"><span class="hint">Ví dụ: 1 THÙNG Pepsi = 24 LON. Để trống/0 nếu không dùng quy đổi.</span></div><div class="field"><label>Báo sắp hết khi còn</label><input id="pMin" type="number" inputmode="decimal" min="0" step="0.001" value="${p?.minStock??0}"></div><div class="field"><label>Giá nhập một đơn vị tồn kho</label><input id="pPrice" type="number" inputmode="numeric" min="0" step="1" value="${p?.unitPrice??0}"></div><div class="field"><label>Mức muốn có sau khi mua</label><input id="pTarget" type="number" inputmode="decimal" min="0" step="0.001" value="${p?.targetStock??0}"><span class="hint">Dùng để gợi ý số lượng cần mua.</span></div></div></details></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Không lưu</button><button class="btn primary large" onclick="saveProduct(${id||'null'},${afterCreateTxType?`'${afterCreateTxType}'`:'null'})">${p?'Lưu thay đổi':'Thêm vào kho'}</button></div>`) }
async function saveProduct(id,afterCreateTxType){let body={sku:$('pSku').value,name:$('pName').value,unit:$('pUnit').value,category:$('pCategory').value,minStock:Number($('pMin').value||0),unitPrice:Number($('pPrice').value||0),targetStock:Number($('pTarget').value||0),packageUnit:$('pPackageUnit').value,unitsPerPackage:Number($('pUnitsPerPackage').value||0),openingStock:id?0:Number($('pOpening').value||0),note:$('pNote').value};if(!body.name.trim()||!body.unit.trim()){toast('Vui lòng ghi tên hàng và đơn vị tính.',true);return}try{const saved=await api('/api/products'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(body)});closeModal();await loadAll();toast(id?'Đã lưu thay đổi':'Đã thêm mặt hàng mới vào kho');if(!id&&afterCreateTxType)setTimeout(()=>openTx(afterCreateTxType,saved.id),50)}catch(e){toast(e.message,true)}}
async function openOpeningStock(id){const p=state.products.find(x=>x.id===id);if(!p)return;try{const r=await api('/api/products/'+id+'/opening-stock?_='+Date.now());openModal('Sửa tồn đầu — '+p.name,`<div class="note" style="margin-bottom:14px">Chỉ dùng khi <b>số tồn đầu ban đầu nhập sai</b>. Phần mềm sẽ tự điều chỉnh tồn hiện tại theo phần chênh lệch và ghi vào Nhật ký. Không sửa trực tiếp số “Còn lại”.</div><div class="confirm-box">Tồn hiện tại: <b>${num.format(p.quantity)} ${esc(p.unit)}</b><br>Tồn đầu đang lưu: <b>${num.format(r.openingStock)} ${esc(p.unit)}</b></div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Tồn đầu mới *</label><input id="openingStockValue" type="number" min="0" step="0.001" value="${r.openingStock??0}"></div><div class="field full"><label>Lý do sửa</label><input id="openingStockNote" placeholder="Ví dụ: nhập nhầm tồn đầu từ Excel"></div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary large" onclick="saveOpeningStock(${id})">Lưu tồn đầu</button></div>`)}catch(e){toast(e.message,true)}}
async function saveOpeningStock(id){const v=Number($('openingStockValue').value);if(!Number.isFinite(v)||v<0){toast('Tồn đầu phải lớn hơn hoặc bằng 0.',true);return}try{await api('/api/products/'+id+'/opening-stock',{method:'PUT',body:JSON.stringify({openingStock:v,note:$('openingStockNote').value})});closeModal();await loadAll();toast('Đã sửa tồn đầu và tự tính lại tồn hiện tại.')}catch(e){toast(e.message,true)}}
function localDateInputValue(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function defaultDrinkReportDate(){const d=new Date();d.setDate(d.getDate()-1);return localDateInputValue(d)}
function openDrinkMonthlyImport(){openModal('🥤 Import Nước',`<div class="note" style="margin-bottom:14px">Dành cho file Nước của quán. Phần mềm hỗ trợ cả <b>file báo cáo đầy đủ</b> và <b>file đơn giản chỉ có Tên hàng / ĐVT / Tồn cuối</b>. Bạn phải <b>chọn đúng ngày cần nhập</b>, ví dụ <b>07/09/2026</b>. <b>Cột Tồn cuối (hoặc Còn lại/Tồn kho) là số Còn lại được đưa vào kho.</b> Nếu file không ghi ngày thì phần mềm dùng chính ngày bạn chọn trên màn hình. Các bảng phụ không phù hợp sẽ bị bỏ qua.</div><div class="note danger" style="margin-bottom:14px"><b>Đã lỡ import sai trước đó?</b> Bấm “Hoàn tác lần import Nước gần nhất” trước, rồi mới import lại file đúng. Phần mềm sẽ kiểm tra và chặn nếu sau lần import đó đã có phiếu mới.</div><div class="form-grid"><div class="field"><label>Chọn đúng ngày cần nhập *</label><input id="drinkTargetDate" type="date" value="${defaultDrinkReportDate()}" onchange="previewDrinkMonthly()"><span class="hint"><b>Phần mềm chỉ đọc đúng ngày này.</b> Ví dụ cần ngày 7/9 thì chọn 07/09/2026; không tự chuyển sang 8/9.</span></div><div class="field full"><label>Chọn file Nước (.xlsx/.xls)</label><input id="drinkMonthlyFile" type="file" accept=".xlsx,.xls" onchange="previewDrinkMonthly()"></div></div><div id="drinkMonthlyPreview" class="empty" style="padding:20px 8px">Chọn file để kiểm tra dữ liệu Nước trước.</div><div class="modal-actions" style="justify-content:space-between;gap:10px;flex-wrap:wrap"><button class="btn danger" onclick="undoLastDrinkImport()">↩ Hoàn tác lần import Nước gần nhất</button><div style="display:flex;gap:8px"><button class="btn" onclick="closeModal()">Hủy</button><button id="drinkMonthlyImportBtn" class="btn green large" disabled onclick="importDrinkMonthly()">Nhập Nước</button></div></div>`)}
async function uploadDrinkMonthly(url,file,targetDate){const fd=new FormData();fd.append('file',file);fd.append('targetDate',targetDate);const r=await fetch(url,{method:'POST',body:fd,credentials:'same-origin'});if(r.status===401){showAuth('Phiên đã khóa. Nhập mật khẩu để mở lại.');throw new Error('Cần đăng nhập lại')}if(!r.ok){let m='Không đọc được báo cáo Nước';try{m=(await r.json()).message||m}catch{}throw new Error(m)}return r.json()}
async function previewDrinkMonthly(){const file=$('drinkMonthlyFile')?.files?.[0],targetDate=$('drinkTargetDate')?.value;if(!file||!targetDate)return;$('drinkMonthlyPreview').innerHTML='<div class="empty">Đang tìm báo cáo Nước đúng ngày đã chọn...</div>';$('drinkMonthlyImportBtn').disabled=true;try{const p=await uploadDrinkMonthly('/api/products/import-drink-monthly/preview',file,targetDate);const warn=(p.warnings||[]).map(x=>`<div style="margin-top:5px">⚠️ ${esc(x)}</div>`).join('');const sample=(p.sample||[]).map(x=>`<div class="tx"><div><b>${esc(x.name)}</b><br><small>${esc(x.unit||'Chưa rõ ĐVT')}</small></div><div>Tồn đầu <b>${num.format(x.openingStock||0)}</b><br>Tồn cuối <b>${num.format(x.closingStock||0)}</b></div><div>Nhập <b>+${num.format(x.inQty||0)}</b><br>Xuất <b>-${num.format(x.outQty||0)}</b>${Number(x.htQty||0)>0?`<br>HT <b>-${num.format(x.htQty)}</b>`:''}</div></div>`).join('');$('drinkMonthlyPreview').innerHTML=`<div class="confirm-box"><b>Đúng báo cáo Nước cần nhập</b><br><b>Chỉ TỒN CUỐI sẽ trở thành số Còn lại trong kho.</b><br>Sheet: <b>${esc(p.sheet)}</b><br>Ngày báo cáo: <b>${formatDateOnly(p.reportDate)}</b><br>${p.products} mặt hàng · ${p.newProducts} hàng mới · ${p.existingProducts} hàng đã có<br>Tổng Nhập: <b>+${num.format(p.totalIn||0)}</b> · Tổng Xuất: <b>-${num.format(p.totalOut||0)}</b>${Number(p.totalHt||0)>0?` · HT: <b>-${num.format(p.totalHt)}</b>`:''}</div>${warn}${sample?`<div style="margin-top:10px">${sample}</div>`:''}`;$('drinkMonthlyImportBtn').disabled=false}catch(e){$('drinkMonthlyPreview').innerHTML=`<div class="note danger">${esc(e.message)}</div>`;toast(e.message,true)}}
async function importDrinkMonthly(){const file=$('drinkMonthlyFile')?.files?.[0],targetDate=$('drinkTargetDate')?.value;if(!file||!targetDate)return;const btn=$('drinkMonthlyImportBtn');btn.disabled=true;btn.textContent='Đang nhập...';try{const r=await uploadDrinkMonthly('/api/products/import-drink-monthly',file,targetDate);closeModal();await loadAll();toast(`Đã cập nhật Tồn cuối Nước ngày ${formatDateOnly(r.reportDate)}. ${r.productsCreated} hàng mới, ${r.stocksSynced} hàng được đưa về đúng Tồn cuối; ${r.rowsSkippedBecauseNewerHistory} hàng có lịch sử mới hơn được giữ nguyên.`)}catch(e){btn.disabled=false;btn.textContent='Nhập Nước';toast(e.message,true)}}

async function undoLastDrinkImport(){try{const p=await api('/api/products/import-drink-monthly/undo-last/preview');if(!p.available){toast((p.warnings||[])[0]||'Không có lần import Nước nào để hoàn tác',true);return}const warning=(p.warnings||[]).join('\n');const msg=`Sắp hoàn tác lần import Nước ngày ${formatDateOnly(p.reportDate)}.\n\n- ${p.transactions} phiếu do import tạo ra sẽ được gỡ\n- ${p.productsAffected} mặt hàng được đưa về trạng thái trước import\n- ${p.removableProducts} mặt hàng chỉ được tạo bởi lần import này có thể bị xóa\n\n${warning?warning+'\n\n':''}Hành động này chỉ nên dùng để sửa lần import sai. Tiếp tục?`;if(!confirm(msg))return;const confirm2=prompt('Để xác nhận, nhập HOAN TAC');if((confirm2||'').trim().toUpperCase()!=='HOAN TAC'){toast('Đã hủy hoàn tác');return}const r=await api('/api/products/import-drink-monthly/undo-last',{method:'POST'});closeModal();await loadAll();toast(`Đã hoàn tác import Nước ${formatDateOnly(r.reportDate)}: gỡ ${r.transactionsRemoved} phiếu, khôi phục ${r.productsRestored} mặt hàng${r.productsRemoved?`, xóa ${r.productsRemoved} hàng chỉ do import tạo`:''}.`)}catch(e){toast(e.message,true)}}

function updateExcelModeHint(){const m=$('excelMode')?.value;if(!$('excelModeHint'))return;$('excelModeHint').textContent=m==='SYNC_STOCK'?'Tồn hiện tại sẽ được đưa về đúng số trong Excel. Hệ thống ghi một phiếu điều chỉnh riêng, không tính nhầm vào Nhập/Xuất báo cáo.':m==='UPDATE_INFO'?'Chỉ cập nhật nhóm hàng và ghi chú. Số tồn hiện tại không thay đổi.':'Không thay đổi bất kỳ hàng nào đã tồn tại; chỉ thêm mặt hàng mới.'}
async function uploadExcel(url,file,mode){const fd=new FormData();fd.append('file',file);if(mode)fd.append('mode',mode);const r=await fetch(url,{method:'POST',body:fd,credentials:'same-origin'});if(r.status===401){showAuth('Phiên đã khóa. Nhập mật khẩu để mở lại.');throw new Error('Cần đăng nhập lại')}if(!r.ok){let m='Không đọc được file Excel';try{m=(await r.json()).message||m}catch{}throw new Error(m)}return r.json()}
async function previewExcel(){const file=$('excelFile').files[0];if(!file)return;$('excelPreview').innerHTML='<div class="empty">Đang kiểm tra file...</div>';$('excelImportBtn').disabled=true;try{const p=await uploadExcel('/api/products/import-excel/preview',file);let warn=(p.warnings||[]).map(x=>`<div style="margin-top:5px">⚠️ ${esc(x)}</div>`).join('');let sample=(p.sample||[]).slice(0,6).map(x=>`<div class="tx"><div>${esc(x.sheet)}</div><div><b>${esc(x.name)}</b><br><small>${esc(x.category)} · ${esc(x.unit)}${x.sku?' · '+esc(x.sku):''}</small></div><div><b>${num.format(x.stock)}</b></div></div>`).join('');$('excelPreview').innerHTML=`<div class="confirm-box"><b>Đã đọc được ${esc(p.detectedFormat||'file Excel')}.</b><br>• Tìm thấy: <b>${p.found}</b> dòng hàng hợp lệ<br>• Hàng mới: <b>${p.canAdd}</b><br>• Hàng đã có / dòng trùng: <b>${p.existing}</b><br>• Dòng chưa hợp lệ: <b>${p.invalid}</b><br>• Sheet nhận được: <b>${(p.sheets||[]).map(esc).join(', ')}</b></div>${sample?`<div style="margin-top:12px"><b>Xem thử trước khi nhập:</b>${sample}</div>`:''}${warn?`<div class="note" style="margin-top:12px">${warn}</div>`:''}`;$('excelImportBtn').disabled=p.found<=0}catch(e){$('excelPreview').innerHTML=`<div class="note" style="color:var(--red)">${esc(e.message)}</div>`}}
async function importExcel(){const file=$('excelFile').files[0];if(!file)return;const mode=$('excelMode').value;if(mode==='SYNC_STOCK'&&!confirm('Đồng bộ tồn theo Excel sẽ thay đổi số tồn của các hàng đã có. Bạn đã kiểm tra đúng file chưa?'))return;const btn=$('excelImportBtn');btn.disabled=true;btn.textContent='Đang xử lý Excel...';try{const r=await uploadExcel('/api/products/import-excel',file,mode);closeModal();await loadAll();let parts=[`thêm ${r.added} hàng mới`];if(r.updated)parts.push(`cập nhật ${r.updated} hàng`);if(r.stockSynced)parts.push(`đồng bộ tồn ${r.stockSynced} hàng`);if(r.skipped)parts.push(`bỏ qua ${r.skipped} dòng`);toast('Excel: '+parts.join(' · '))}catch(e){btn.disabled=false;btn.textContent='Thực hiện nhập Excel';toast(e.message,true)}}
async function deleteProduct(id){try{await loadAll();const p=state.products.find(x=>x.id===id);if(!p){toast('Mặt hàng này không còn tồn tại trong dữ liệu. Danh sách đã được tải lại.',true);return}if(!confirm(`Bạn muốn xóa “${p.name}”?\n\nNếu mặt hàng KHÔNG có phiếu Nhập/Xuất thật, phần mềm sẽ xóa luôn mặt hàng cùng Tồn đầu / Điều chỉnh / Kiểm kê liên quan. Nếu đã từng Nhập hoặc Xuất thật thì sẽ không cho xóa.`))return;await api('/api/products/'+id,{method:'DELETE'});closeModal();await loadAll();toast('Đã xóa mặt hàng')}catch(e){await loadAll();toast(e.message,true)}}
function txProductChanged(){const p=state.products.find(x=>x.id===Number($('txProduct').value));if(!p)return;const hasPack=p.packageUnit&&Number(p.unitsPerPackage)>1;$('txStockInfo').textContent=`Hiện còn: ${num.format(p.quantity)} ${p.unit}${hasPack?` (≈ ${num.format(Number(p.quantity)/Number(p.unitsPerPackage))} ${p.packageUnit})`:''}`;const u=$('txEntryUnit');if(u){u.innerHTML=`<option value="${esc(p.unit)}">${esc(p.unit)} (đơn vị lẻ)</option>`+(hasPack?`<option value="${esc(p.packageUnit)}">${esc(p.packageUnit)} — 1 ${esc(p.packageUnit)} = ${num.format(p.unitsPerPackage)} ${esc(p.unit)}</option>`:'');}if($('txCost')&&!$('txCost').value&&Number(p.unitPrice)>0)$('txCost').value=Number(p.unitPrice)}
function openTx(type,selectedProductId){if(!state.products.length){openModal('Chưa có mặt hàng',`<div class="empty">Trước khi nhập hoặc xuất, hãy thêm mặt hàng đầu tiên.<br><button class="btn primary large" onclick="closeModal();openProduct(null,'${type}')">＋ Thêm mặt hàng mới</button></div>`);return}let opts=state.products.map(p=>`<option value="${p.id}" ${Number(selectedProductId)===p.id?'selected':''}>${esc(p.name)}</option>`).join('');let addNew=type==='IN'?`<button type="button" class="btn small" style="margin-top:8px" onclick="closeModal();openProduct(null,'IN')">＋ Hàng chưa có? Thêm mới</button>`:'';let reportFields=type==='IN'?`<details class="optional"><summary>Thông tin cho Bảng nhập hàng (không bắt buộc)</summary><div class="form-grid" style="margin-top:12px"><div class="field full"><label>Nhà cung cấp</label><input id="txSupplier" placeholder="Ví dụ: NCC Ngọc Phước"></div><div class="field"><label>Người ký nhận</label><input id="txReceiver" placeholder="Tên người nhận hàng"></div><div class="field"><label><input id="txInvoiceSent" type="checkbox" style="width:auto;margin-right:8px">Đã gửi hình hóa đơn</label></div></div></details>`:`<details class="optional"><summary>Thông tin cho Phiếu xuất kho (không bắt buộc)</summary><div class="form-grid" style="margin-top:12px"><div class="field"><label>Người nhận hàng</label><input id="txReceiver" placeholder="Tên người nhận"></div><div class="field"><label>Bộ phận</label><input id="txDepartment" placeholder="Ví dụ: BẾP"></div><div class="field"><label>Tên nhân viên</label><input id="txEmployee" placeholder="Ví dụ: YẾN"></div></div></details>`;openModal(type==='IN'?'📥 Nhập hàng vào kho':'📤 Xuất hàng khỏi kho',`<div class="form-grid"><div class="field full"><label>Chọn hàng *</label><select id="txProduct" onchange="txProductChanged()">${opts}</select><span class="hint" id="txStockInfo"></span>${addNew}</div><div class="field"><label>Ngày giờ phiếu *</label><input id="txOccurredAt" type="datetime-local" value="${dateTimeLocalValue()}"></div><div class="field"><label>Số lượng *</label><input id="txQty" type="number" inputmode="decimal" min="0.001" step="0.001" autofocus placeholder="Nhập số lượng"></div><div class="field"><label>Nhập/xuất theo đơn vị</label><select id="txEntryUnit"></select><span class="hint">Nếu mặt hàng có quy đổi, có thể chọn THÙNG/KÉT hoặc LON/CHAI.</span></div><div class="field"><label>${type==='IN'?'Giá nhập một đơn vị':'Đơn giá tham khảo'}</label><input id="txCost" type="number" inputmode="numeric" min="0" step="1" placeholder="Có thể bỏ trống"></div><div class="field full"><label>Ghi chú</label><textarea id="txNote" rows="2" placeholder="${type==='IN'?'Ví dụ: số hóa đơn / ghi chú thêm':'Ví dụ: lý do xuất / ghi chú thêm'} (không bắt buộc)"></textarea></div><div class="field full">${reportFields}</div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Hủy</button><button class="btn ${type==='IN'?'green':'red'} large" onclick="confirmTx('${type}')">Tiếp tục</button></div>`);setTimeout(txProductChanged,0)}
function confirmTx(type){const p=state.products.find(x=>x.id===Number($('txProduct').value)),qty=Number($('txQty').value),occurredAt=$('txOccurredAt').value,entryUnit=$('txEntryUnit').value;if(!p||!qty||qty<=0){toast('Vui lòng nhập số lượng lớn hơn 0.',true);return}if(!occurredAt){toast('Vui lòng chọn ngày giờ của phiếu.',true);return}if(new Date(occurredAt).getTime()>Date.now()+5*60*1000){toast('Ngày giờ phiếu không thể ở tương lai.',true);return}const factor=(p.packageUnit&&entryUnit===p.packageUnit&&Number(p.unitsPerPackage)>1)?Number(p.unitsPerPackage):1,baseQty=qty*factor;if(type==='OUT'&&baseQty>Number(p.quantity)){toast(`Không đủ hàng. ${num.format(qty)} ${entryUnit} tương đương ${num.format(baseQty)} ${p.unit}, nhưng hiện chỉ còn ${num.format(p.quantity)} ${p.unit}.`,true);return}const cost=$('txCost').value,note=$('txNote').value;pendingTx={productId:p.id,type,quantity:qty,entryUnit,unitCost:cost?Number(cost):null,note,supplier:$('txSupplier')?.value||null,receiverName:$('txReceiver')?.value||null,invoiceSent:$('txInvoiceSent')?.checked||false,department:$('txDepartment')?.value||null,employeeName:$('txEmployee')?.value||null,occurredAt};openModal(type==='IN'?'Xác nhận nhập hàng':'Xác nhận xuất hàng',`<div class="confirm-box"><b>${type==='IN'?'Nhập vào':'Xuất ra'}:</b> ${num.format(qty)} ${esc(entryUnit)}${factor>1?` = <b>${num.format(baseQty)} ${esc(p.unit)}</b>`:''}<br><b>Mặt hàng:</b> ${esc(p.name)}<br><b>Ngày giờ phiếu:</b> ${new Date(occurredAt).toLocaleString('vi-VN')}${cost?`<br><b>Đơn giá:</b> ${money.format(Number(cost))}`:''}${pendingTx.supplier?`<br><b>Nhà cung cấp:</b> ${esc(pendingTx.supplier)}`:''}${pendingTx.receiverName?`<br><b>Người nhận/ký nhận:</b> ${esc(pendingTx.receiverName)}`:''}${pendingTx.department?`<br><b>Bộ phận:</b> ${esc(pendingTx.department)}`:''}${pendingTx.employeeName?`<br><b>Nhân viên:</b> ${esc(pendingTx.employeeName)}`:''}${note?`<br><b>Ghi chú:</b> ${esc(note)}`:''}</div><p class="note">Tồn kho luôn được lưu theo ${esc(p.unit)} để nhập theo thùng nhưng xuất lẻ vẫn chính xác.</p><div class="modal-actions"><button class="btn" onclick="openTx('${type}',${p.id})">Quay lại sửa</button><button class="btn ${type==='IN'?'green':'red'} large" onclick="savePendingTx()">${type==='IN'?'Xác nhận nhập':'Xác nhận xuất'}</button></div>`) }
async function savePendingTx(){if(!pendingTx)return;const tx={...pendingTx};try{const created=await api('/api/inventory',{method:'POST',body:JSON.stringify(tx)});pendingTx=null;closeModal();await loadAll();toast(tx.type==='IN'?'Đã nhập hàng vào kho':'Đã xuất hàng khỏi kho',false,'Hoàn tác',()=>undoTransaction(created.id),9000)}catch(e){toast(e.message,true)}}
async function undoTransaction(id){await api('/api/inventory/'+id,{method:'DELETE'});await loadAll();toast('Đã hoàn tác thao tác vừa rồi')}
function maybeShowLowStockAlert(){if(state.lowStockAlertShown||!state.products.length)return;const low=state.products.filter(p=>Number(p.quantity)<=Number(p.minStock));if(!low.length)return;state.lowStockAlertShown=true;const shown=low.slice(0,5);openModal('⚠️ Có hàng cần chú ý',`<p>Hiện có <b>${low.length} mặt hàng</b> đã hết hoặc sắp hết.</p><div class="low-stock-alert">${shown.map(p=>`<div class="item"><span><b>${esc(p.name)}</b><br><small>Còn ${num.format(p.quantity)} ${esc(p.unit)}</small></span><span class="badge ${status(p)[1]}">${status(p)[0]}</span></div>`).join('')}</div>${low.length>5?`<p class="note">Còn ${low.length-5} mặt hàng khác.</p>`:''}<div class="modal-actions"><button class="btn" onclick="closeModal()">Để sau</button><button class="btn primary large" onclick="closeModal();showPage('operations')">Xem hàng cần mua</button></div>`)}
function openEditTx(id){const t=state.tx.find(x=>x.id===id);if(!t||t.status!=='COMPLETED'||!['IN','OUT'].includes(t.type))return;const extra=t.type==='IN'?`<div class="field full"><label>Nhà cung cấp</label><input id="etSupplier" value="${esc(t.supplier||'')}"></div><div class="field"><label>Người ký nhận</label><input id="etReceiver" value="${esc(t.receiverName||'')}"></div><div class="field"><label><input id="etInvoiceSent" type="checkbox" style="width:auto;margin-right:8px" ${t.invoiceSent?'checked':''}>Đã gửi hình hóa đơn</label></div>`:`<div class="field"><label>Người nhận hàng</label><input id="etReceiver" value="${esc(t.receiverName||'')}"></div><div class="field"><label>Bộ phận</label><input id="etDepartment" value="${esc(t.department||'')}"></div><div class="field"><label>Tên nhân viên</label><input id="etEmployee" value="${esc(t.employeeName||'')}"></div>`;openModal(t.type==='IN'?'Sửa phiếu nhập':'Sửa phiếu xuất',`<div class="confirm-box"><b>Mặt hàng:</b> ${esc(t.productName)}<br><b>Phiếu:</b> ${esc(t.code)}<br><small>Có thể sửa số lượng, ngày giờ và thông tin phiếu. Không đổi mặt hàng hoặc loại phiếu để tránh sai tồn kho.</small></div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Ngày giờ phiếu *</label><input id="etOccurredAt" type="datetime-local" value="${dateTimeLocalValue(t.createdAt)}"><span class="hint">Ví dụ có thể đổi phiếu sang ngày hôm qua.</span></div><div class="field"><label>Số lượng *</label><input id="etQty" type="number" inputmode="decimal" min="0.001" step="0.001" value="${t.enteredQuantity??t.quantity}"><span class="hint">Tồn kho sẽ tự tăng/giảm theo phần chênh lệch.</span></div><div class="field"><label>Đơn vị</label><select id="etEntryUnit">${(()=>{const p=state.products.find(x=>x.id===t.productId);let h=`<option value="${esc(t.unit)}">${esc(t.unit)}</option>`;if(p?.packageUnit&&Number(p.unitsPerPackage)>1)h+=`<option value="${esc(p.packageUnit)}" ${(t.enteredUnit||t.unit)===p.packageUnit?'selected':''}>${esc(p.packageUnit)} — 1 = ${num.format(p.unitsPerPackage)} ${esc(p.unit)}</option>`;return h})()}</select></div><div class="field"><label>Đơn giá</label><input id="etCost" type="number" min="0" step="1" value="${t.unitCost??''}"></div><div class="field full"><label>Ghi chú</label><textarea id="etNote" rows="2">${esc(t.note||'')}</textarea></div>${extra}</div><div class="modal-actions"><button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary large" onclick="saveEditTx(${id})">Lưu thay đổi</button></div>`)}
async function saveEditTx(id){const t=state.tx.find(x=>x.id===id),qty=Number($('etQty').value),occurredAt=$('etOccurredAt').value;if(!qty||qty<=0){toast('Số lượng phải lớn hơn 0.',true);return}if(!occurredAt){toast('Vui lòng chọn ngày giờ phiếu.',true);return}if(new Date(occurredAt).getTime()>Date.now()+5*60*1000){toast('Ngày giờ phiếu không thể ở tương lai.',true);return}const body={quantity:qty,unitCost:$('etCost').value?Number($('etCost').value):null,note:$('etNote').value,supplier:$('etSupplier')?.value||null,receiverName:$('etReceiver')?.value||null,invoiceSent:$('etInvoiceSent')?.checked||false,department:$('etDepartment')?.value||null,employeeName:$('etEmployee')?.value||null,occurredAt,entryUnit:$('etEntryUnit')?.value||t.unit};try{await api('/api/inventory/'+id,{method:'PUT',body:JSON.stringify(body)});closeModal();await loadAll();toast(t?.type==='IN'?'Đã sửa phiếu nhập và cập nhật tồn kho':'Đã sửa phiếu xuất và cập nhật tồn kho')}catch(e){toast(e.message,true)}}
async function deleteTx(id,btn){
  const t=state.tx.find(x=>x.id===id);if(!t||state.deletingTxIds.has(id))return;
  const effect=t.type==='OUT'?`Kho sẽ được CỘNG TRẢ LẠI ${num.format(t.quantity)} ${t.unit}.`:`Kho sẽ bị TRỪ ${num.format(t.quantity)} ${t.unit} đã nhập từ phiếu này.`;
  if(!confirm(`Xóa ${t.type==='OUT'?'phiếu xuất':'phiếu nhập'} này?\n\n${t.productName}: ${num.format(t.quantity)} ${t.unit}\nNgày giờ: ${new Date(t.createdAt).toLocaleString('vi-VN')}\n\n${effect}\n\nThao tác này sẽ xóa phiếu khỏi sổ nhập xuất.`))return;
  state.deletingTxIds.add(id);if(btn){btn.disabled=true;btn.textContent='Đang xóa…'}
  try{
    const result=await api('/api/inventory/'+id,{method:'DELETE'});
    // Server đã xác nhận commit/flush xong: cập nhật giao diện ngay, không chờ lần tải kế tiếp.
    state.tx=state.tx.filter(x=>x.id!==id);
    const p=state.products.find(x=>x.id===result?.productId);
    if(p&&result?.quantityAfterDelete!=null)p.quantity=result.quantityAfterDelete;
    renderAll();
    toast(t.type==='OUT'?'Đã xóa phiếu xuất và trả hàng lại kho':'Đã xóa phiếu nhập và trừ hàng khỏi kho');
    // Đồng bộ lại toàn bộ dữ liệu từ server; no-store + cache-buster tránh dữ liệu cũ.
    await loadAll();
  }catch(e){
    // Nếu request đầu đã xóa thành công nhưng response bị mất/nhấn lặp, kiểm tra server.
    try{
      const latest=await api('/api/inventory?_='+Date.now());
      if(!latest.some(x=>x.id===id)){
        state.tx=latest;renderAll();
        toast(t.type==='OUT'?'Phiếu đã được xóa và hàng đã được trả lại kho':'Phiếu đã được xóa và tồn kho đã được điều chỉnh');
        await loadAll();return;
      }
    }catch(_){ }
    toast(e.message||'Không xóa được phiếu. Vui lòng thử lại.',true);
  }finally{
    state.deletingTxIds.delete(id);
    const b=document.querySelector(`[data-delete-tx="${id}"]`);if(b){b.disabled=false;b.textContent='Xóa'}
  }
}
async function voidTx(id){const t=state.tx.find(x=>x.id===id);if(!confirm(`Sửa sai phiếu này?\n\n${t?.productName||''}: ${num.format(t?.quantity||0)} ${t?.unit||''}\n\nPhần mềm sẽ tự điều chỉnh tồn kho ngược lại.`))return;try{await api('/api/inventory/'+id+'/void',{method:'POST'});await loadAll();toast('Đã sửa sai và điều chỉnh lại tồn kho')}catch(e){toast(e.message,true)}}

async function deleteWaterAdjustmentFromList(id){const t=state.tx.find(x=>x.id===id);if(!t)return;if(!confirm(`Xóa dòng chốt tồn Nước này?\n\n${t.productName}: ${t.type==='ADJUST_OUT'?'−':'+'}${num.format(t.quantity)} ${t.unit}\nNgày giờ: ${new Date(t.createdAt).toLocaleString('vi-VN')}\n\nTồn kho sẽ được tính ngược lại sau khi xóa. Phiếu Nhập/Xuất thật không bị ảnh hưởng.`))return;try{await api('/api/inventory/'+id,{method:'DELETE'});await loadAll();toast('Đã xóa dòng chốt tồn Nước và cập nhật lại tồn kho')}catch(e){toast(e.message||'Không xóa được điều chỉnh.',true)}}

function historyTypeLabel(t){return t==='IN'?'Nhập':t==='OUT'?'Xuất':t==='OPENING'?'Tồn đầu':'Điều chỉnh'}
function historyTypeClass(t){return t==='IN'?'movement-in':t==='OUT'?'movement-out':'movement-other'}
function historySigned(t,q){const outward=t==='OUT'||t==='ADJUST_OUT';return `${outward?'−':'+'}${num.format(q)}`}
async function openProductHistory(id){
  try{
    productHistoryData=await api('/api/inventory/product/'+id+'/history?_='+Date.now());productHistoryProductId=id;
    const h=productHistoryData;
    openModal('Lịch sử: '+h.productName,`<div class="confirm-box"><b>${esc(h.productName)}</b>${h.sku?` · Mã ${esc(h.sku)}`:''}<br><span>Nhóm: ${esc(h.category||'Khác')} · ĐVT: ${esc(h.unit)}</span></div>
      <div class="history-summary"><div class="mini-stat"><span>Tồn hiện tại</span><b>${num.format(h.currentStock)} ${esc(h.unit)}</b></div><div class="mini-stat"><span>Tổng đã nhập</span><b class="movement-in">+${num.format(h.totalIn)}</b></div><div class="mini-stat"><span>Tổng đã xuất</span><b class="movement-out">−${num.format(h.totalOut)}</b></div><div class="mini-stat"><span>Số phiếu nhập/xuất</span><b>${h.transactionCount}</b></div></div>
      <div class="toolbar"><select id="historyType" onchange="renderProductHistoryRows()"><option value="ALL">Tất cả biến động</option><option value="IN">Chỉ nhập</option><option value="OUT">Chỉ xuất</option><option value="OTHER">Tồn đầu / điều chỉnh</option></select><input id="historyFrom" type="date" onchange="renderProductHistoryRows()"><input id="historyTo" type="date" onchange="renderProductHistoryRows()"></div>
      <div class="history-toolbar"><button class="btn small" onclick="setHistoryPeriod('ALL')">Tất cả</button><button class="btn small" onclick="setHistoryPeriod('TODAY')">Hôm nay</button><button class="btn small" onclick="setHistoryPeriod('7D')">7 ngày</button><button class="btn small" onclick="setHistoryPeriod('30D')">30 ngày</button><button class="btn small" onclick="setHistoryPeriod('MONTH')">Tháng này</button><button class="btn green small" onclick="exportProductHistoryExcel()">📊 Xuất lịch sử Excel</button></div>
      <div id="historyFilterSummary" class="note" style="margin-bottom:10px"></div>
      <div class="table-wrap"><table class="table" style="min-width:1060px"><thead><tr><th>Ngày giờ</th><th>Loại</th><th class="right">Biến động</th><th class="right">Tồn sau phiếu</th><th>Mã phiếu</th><th>Thông tin</th><th>Ghi chú</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody id="historyRows"></tbody></table></div>
      <div class="modal-actions"><button class="btn green" onclick="openTx('IN',${id})">📥 Nhập món này</button><button class="btn red" onclick="openTx('OUT',${id})">📤 Xuất món này</button><button class="btn" onclick="closeModal()">Đóng</button></div>`);
    $('modal').classList.add('history');setHistoryPeriod('ALL');
  }catch(e){toast(e.message,true)}
}
function setHistoryPeriod(period){
  const from=$('historyFrom'),to=$('historyTo');if(!from||!to)return;const now=new Date(),fmt=d=>{const x=new Date(d.getTime()-d.getTimezoneOffset()*60000);return x.toISOString().slice(0,10)};
  to.value=fmt(now);if(period==='ALL'){from.value='';to.value=''}else if(period==='TODAY'){from.value=fmt(now)}else if(period==='7D'){const d=new Date(now);d.setDate(d.getDate()-6);from.value=fmt(d)}else if(period==='30D'){const d=new Date(now);d.setDate(d.getDate()-29);from.value=fmt(d)}else if(period==='MONTH'){const d=new Date(now.getFullYear(),now.getMonth(),1);from.value=fmt(d)}renderProductHistoryRows();
}
function filteredProductHistory(){
  if(!productHistoryData)return[];const type=$('historyType')?.value||'ALL',from=$('historyFrom')?.value,to=$('historyTo')?.value;
  return productHistoryData.transactions.filter(t=>{const d=String(t.createdAt).slice(0,10);if(from&&d<from)return false;if(to&&d>to)return false;if(type==='IN'&&t.type!=='IN')return false;if(type==='OUT'&&t.type!=='OUT')return false;if(type==='OTHER'&&['IN','OUT'].includes(t.type))return false;return true});
}
function renderProductHistoryRows(){
  const h=productHistoryData;if(!h||!$('historyRows'))return;const rows=filteredProductHistory();let inQty=0,outQty=0;rows.forEach(t=>{if(t.status==='COMPLETED'&&t.type==='IN')inQty+=Number(t.quantity);if(t.status==='COMPLETED'&&t.type==='OUT')outQty+=Number(t.quantity)});
  $('historyFilterSummary').innerHTML=`Đang hiển thị <b>${rows.length}</b> dòng · Nhập trong phần đang xem: <b class="movement-in">${num.format(inQty)} ${esc(h.unit)}</b> · Xuất: <b class="movement-out">${num.format(outQty)} ${esc(h.unit)}</b>`;
  $('historyRows').innerHTML=rows.length?rows.map(t=>{const info=t.type==='IN'?(t.supplier||t.receiverName||''):t.type==='OUT'?([t.department,t.employeeName,t.receiverName].filter(Boolean).join(' · ')):'';let actions='';if(t.status==='COMPLETED'&&(t.type==='IN'||t.type==='OUT')){actions=`<button class="btn small red" onclick="deleteHistoryInOut(${t.id})">Xóa</button>`}else if(t.deletableDrinkAdjustment){actions=`<button class="btn small red" onclick="deleteDrinkAdjustment(${t.id})">Xóa</button>`}return `<tr><td>${new Date(t.createdAt).toLocaleString('vi-VN')}</td><td><span class="${historyTypeClass(t.type)}">${historyTypeLabel(t.type)}</span></td><td class="right ${historyTypeClass(t.type)}">${historySigned(t.type,t.quantity)} ${esc(h.unit)}${t.enteredQuantity&&t.enteredUnit&&Number(t.conversionFactor)>1?`<br><small>${num.format(t.enteredQuantity)} ${esc(t.enteredUnit)}</small>`:''}</td><td class="right"><b>${num.format(t.balanceAfter)}</b> ${esc(h.unit)}</td><td><small>${esc(t.code)}</small></td><td class="history-detail">${esc(info||'—')}</td><td class="history-detail">${esc(cleanTxNote(t.note)||'—')}</td><td>${t.status==='COMPLETED'?'<span class="badge ok">Hoàn tất</span>':'<span class="badge void">Đã sửa sai</span>'}</td><td>${actions}</td></tr>`}).join(''):`<tr><td colspan="9" class="empty">Không có nhập/xuất trong khoảng thời gian đã chọn.</td></tr>`;
}
async function deleteDrinkAdjustment(id){
  const h=productHistoryData;if(!h)return;const t=h.transactions.find(x=>x.id===id);if(!t)return;
  const sign=(t.type==='ADJUST_OUT'?'−':'+');
  if(!confirm(`Xóa dòng chốt tồn Nước này?\n\n${h.productName}: ${sign}${num.format(t.quantity)} ${h.unit}\nNgày giờ: ${new Date(t.createdAt).toLocaleString('vi-VN')}\n\nTồn kho sẽ được tính ngược lại sau khi xóa. Phiếu nhập/xuất thật không bị ảnh hưởng.`))return;
  const pid=productHistoryProductId;
  try{await api('/api/inventory/'+id,{method:'DELETE'});await loadAll();await openProductHistory(pid);toast('Đã xóa dòng chốt tồn Nước và cập nhật lại tồn kho')}catch(e){toast(e.message||'Không xóa được điều chỉnh.',true)}
}
async function deleteHistoryInOut(id){
  const h=productHistoryData;if(!h)return;const t=h.transactions.find(x=>x.id===id);if(!t||!['IN','OUT'].includes(t.type))return;
  const effect=t.type==='OUT'?`Kho sẽ được cộng trả lại ${num.format(t.quantity)} ${h.unit}.`:`Kho sẽ bị trừ ${num.format(t.quantity)} ${h.unit} của phiếu nhập này.`;
  if(!confirm(`Xóa phiếu ${t.type==='OUT'?'xuất':'nhập'} này?\n\n${h.productName}: ${num.format(t.quantity)} ${h.unit}\nNgày giờ: ${new Date(t.createdAt).toLocaleString('vi-VN')}\nMã phiếu: ${t.code||'—'}\n\n${effect}`))return;
  const pid=productHistoryProductId;
  try{await api('/api/inventory/'+id,{method:'DELETE'});await loadAll();await openProductHistory(pid);toast(t.type==='OUT'?'Đã xóa phiếu xuất và trả hàng lại kho':'Đã xóa phiếu nhập và cập nhật lại tồn kho')}catch(e){toast(e.message||'Không xóa được phiếu.',true)}
}
function exportProductHistoryExcel(){
  if(!productHistoryProductId)return;const type=$('historyType')?.value||'ALL',from=$('historyFrom')?.value||'',to=$('historyTo')?.value||'';const qs=new URLSearchParams({productId:String(productHistoryProductId),type:type});if(from)qs.set('from',from);if(to)qs.set('to',to);window.location.href='/api/reports/product-history.xlsx?'+qs.toString();
}

function openExpense(id){let e=id?state.expenses.find(x=>x.id===id):null;openModal(e?'Sửa khoản chi':'Ghi một khoản chi',`<div class="form-grid"><div class="field"><label>Ngày *</label><input id="eDate" type="date" value="${e?.expenseDate||new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Chi cho việc gì? *</label><input id="eCat" value="${esc(e?.category||'')}" placeholder="Ví dụ: Vận chuyển"></div><div class="field full"><label>Số tiền *</label><input id="eAmount" type="number" inputmode="numeric" min="1" step="1" value="${e?.amount||''}" placeholder="Ví dụ: 150000"></div><div class="field full"><label>Ghi chú</label><textarea id="eNote" rows="2" placeholder="Không bắt buộc">${esc(e?.note||'')}</textarea></div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary large" onclick="saveExpense(${id||'null'})">Lưu khoản chi</button></div>`)}
async function saveExpense(id){let body={expenseDate:$('eDate').value,category:$('eCat').value,amount:Number($('eAmount').value),note:$('eNote').value};if(!body.category.trim()||!body.amount){toast('Vui lòng ghi khoản chi và số tiền.',true);return}try{await api('/api/expenses'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(body)});closeModal();await loadAll();toast('Đã ghi khoản chi')}catch(e){toast(e.message,true)}}
async function deleteExpense(id){if(!confirm('Xóa khoản chi này?'))return;try{await api('/api/expenses/'+id,{method:'DELETE'});await loadAll();toast('Đã xóa khoản chi')}catch(e){toast(e.message,true)}}
function renderOperations(){
  const rows=state.stocktakes||[];$('stocktakeRows').innerHTML=rows.length?rows.map(x=>`<tr><td>${new Date(x.countedAt).toLocaleString('vi-VN')}</td><td><b>${esc(x.productName)}</b><br><small>${esc(x.unit)}</small></td><td class="right">${num.format(x.systemQuantity)}</td><td class="right"><b>${num.format(x.actualQuantity)}</b></td><td class="right"><b class="${Number(x.differenceQuantity)<0?'qty-out':Number(x.differenceQuantity)>0?'qty-in':''}">${Number(x.differenceQuantity)>0?'+':''}${num.format(x.differenceQuantity)}</b></td><td>${esc(x.note||'')}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">Chưa có lần kiểm kê nào.</td></tr>';
  const ps=state.purchases||[];$('purchaseList').innerHTML=ps.length?`<div class="check-list">${ps.map(p=>`<label class="check-row"><input type="checkbox" ${state.purchaseSelected.has(p.id)?'checked':''} onchange="this.checked?state.purchaseSelected.add(${p.id}):state.purchaseSelected.delete(${p.id})"><span><b>${esc(p.name)}</b><br><small>Còn ${num.format(p.currentStock)} ${esc(p.unit)} · báo khi ${num.format(p.minStock)} · muốn có ${num.format(p.targetStock)}</small></span><b>+${num.format(p.suggestedQuantity)}</b></label>`).join('')}</div>`:'<div class="empty">Chưa có mặt hàng nào cần mua thêm.</div>';
}
function openStocktake(productId){const opts=state.products.map(p=>`<option value="${p.id}" ${p.id===productId?'selected':''}>${esc(p.name)} — đang ${num.format(p.quantity)} ${esc(p.unit)}</option>`).join('');openModal('Kiểm kê thực tế',`<div class="note" style="margin-bottom:12px">Hãy đếm số lượng thực tế ngoài kho. Phần mềm sẽ tự tính phần chênh và lưu thành một điều chỉnh kiểm kê.</div><div class="form-grid"><div class="field full"><label>Mặt hàng *</label><select id="stProduct" onchange="syncStocktakeHint()">${opts}</select></div><div class="field"><label>Số lượng đếm thực tế *</label><input id="stActual" type="number" min="0" step="0.001" inputmode="decimal"></div><div class="field"><label>Ngày giờ kiểm kê</label><input id="stAt" type="datetime-local" value="${dateTimeLocalValue()}"></div><div class="field full"><label>Ghi chú</label><textarea id="stNote" rows="2" placeholder="Ví dụ: kiểm kê cuối tuần"></textarea></div></div><div id="stHint" class="confirm-box"></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary large" onclick="saveStocktake()">Xác nhận kiểm kê</button></div>`);$('stActual').addEventListener('input',syncStocktakeHint);syncStocktakeHint()}
function syncStocktakeHint(){const p=state.products.find(x=>x.id===Number($('stProduct')?.value)),actual=Number($('stActual')?.value);if(!p||!$('stHint'))return;const diff=Number.isFinite(actual)?actual-Number(p.quantity):0;$('stHint').innerHTML=`Hệ thống đang ghi <b>${num.format(p.quantity)} ${esc(p.unit)}</b>. ${$('stActual').value!==''?`Nếu xác nhận, tồn sẽ ${diff===0?'giữ nguyên':diff>0?`tăng <b>${num.format(diff)}</b>`:`giảm <b>${num.format(Math.abs(diff))}</b>`}.`: 'Nhập số thực tế để xem chênh lệch.'}`}
async function saveStocktake(){const productId=Number($('stProduct').value),actualQuantity=Number($('stActual').value),countedAt=$('stAt').value;if($('stActual').value===''||actualQuantity<0){toast('Vui lòng nhập số lượng thực tế.',true);return}if(!confirm('Xác nhận số đếm thực tế này?\n\nPhần mềm sẽ tự điều chỉnh tồn nếu có chênh lệch.'))return;try{await api('/api/stocktakes',{method:'POST',body:JSON.stringify({productId,actualQuantity,note:$('stNote').value,countedAt})});closeModal();await loadAll();toast('Đã ghi kiểm kê và cập nhật tồn kho')}catch(e){toast(e.message,true)}}
function togglePurchaseAll(v){state.purchaseSelected.clear();if(v)state.purchases.forEach(x=>state.purchaseSelected.add(x.id));renderOperations()}
async function exportPurchaseList(){const ids=[...state.purchaseSelected];if(!ids.length){toast('Hãy chọn ít nhất một mặt hàng.',true);return}try{const r=await fetch('/api/purchases/excel',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(ids)});if(!r.ok)throw new Error((await r.json()).message||'Không tạo được Excel');const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='danh-sach-can-mua.xlsx';a.click();URL.revokeObjectURL(a.href)}catch(e){toast(e.message,true)}}
function downloadBackup(){window.location.href='/api/backup/export'}
let pendingRestorePreview=null;
async function restoreBackup(input){
  const file=input.files?.[0];if(!file)return;input.value='';
  if(!file.name.toLowerCase().endsWith('.json')){toast('Hãy chọn file .json đã xuất từ Kho Nhà Mình.',true);return}
  const fd=new FormData();fd.append('file',file);
  try{
    const r=await fetch('/api/backup/preview',{method:'POST',credentials:'same-origin',body:fd});let d=null;try{d=await r.json()}catch{}
    if(!r.ok)throw new Error(d?.message||'File không hợp lệ hoặc không đọc được');
    pendingRestoreFile=file;pendingRestorePreview=d;
    const exported=d.exportedAt?new Date(d.exportedAt).toLocaleString('vi-VN'):'Không rõ';
    openModal('Nhập dữ liệu từ máy khác — bước 1/2',`<div class="confirm-box"><b>File:</b> ${esc(file.name)}<br><b>Ngày xuất:</b> ${esc(exported)}<br><br><b>Dữ liệu trong file:</b><ul><li>${num.format(d.products)} mặt hàng</li><li>${num.format(d.transactions)} phiếu/giao dịch</li><li>${num.format(d.expenses)} khoản chi</li><li>${num.format(d.stocktakes)} lần kiểm kê</li><li>${num.format(d.auditEvents)} dòng nhật ký</li></ul></div><div class="restore-step" style="margin-top:12px"><b>Cảnh báo:</b> dữ liệu hiện có trên máy này sẽ được thay thế. Mật khẩu của máy này không đổi. Hãy chắc chắn đây là file bạn muốn chuyển sang.</div><div class="modal-actions"><button class="btn" onclick="cancelRestore()">Hủy</button><button class="btn red large" onclick="confirmRestoreStep2()">Tiếp tục</button></div>`);
  }catch(e){pendingRestoreFile=null;pendingRestorePreview=null;toast(e.message,true)}
}
function cancelRestore(){pendingRestoreFile=null;pendingRestorePreview=null;closeModal()}
function confirmRestoreStep2(){if(!pendingRestoreFile||!pendingRestorePreview)return;const d=pendingRestorePreview;openModal('Nhập dữ liệu — bước 2/2',`<div class="restore-step"><strong>Xác nhận lần cuối</strong><br>Sẽ thay dữ liệu trên máy này bằng <b>${num.format(d.products)} mặt hàng</b>, <b>${num.format(d.transactions)} giao dịch</b> và <b>${num.format(d.expenses)} khoản chi</b> từ file đã chọn.<br><br>Phần mềm tự lưu bản an toàn trước khi nhập. Nếu chọn nhầm file, hãy bấm <b>Hủy</b>.</div><div class="modal-actions"><button class="btn" onclick="cancelRestore()">Hủy</button><button id="restoreConfirmBtn" class="btn red large" onclick="executeRestore()">Xác nhận nhập dữ liệu</button></div>`)}
async function executeRestore(){const file=pendingRestoreFile;if(!file)return;const btn=$('restoreConfirmBtn');if(btn){btn.disabled=true;btn.textContent='Đang nhập dữ liệu…'}const fd=new FormData();fd.append('file',file);try{const r=await fetch('/api/backup/restore',{method:'POST',credentials:'same-origin',body:fd});let data=null;try{data=await r.json()}catch{}if(!r.ok)throw new Error(data?.message||'Không nhập được dữ liệu');pendingRestoreFile=null;pendingRestorePreview=null;closeModal();await loadAll();toast(`Đã chuyển ${data.products} mặt hàng và ${data.transactions} giao dịch sang máy này`)}catch(e){if(btn){btn.disabled=false;btn.textContent='Xác nhận nhập dữ liệu'}toast(e.message,true)}}
async function openAuditLog(){try{const rows=await api('/api/audit?_='+Date.now());openModal('Nhật ký thay đổi',`<div class="note" style="margin-bottom:12px">Dùng khi cần kiểm tra ai đã làm gì trong phần mềm. Vì app chỉ có một người dùng, nhật ký tập trung vào thời gian và nội dung thay đổi.</div><div class="table-wrap"><table class="table"><thead><tr><th>Thời gian</th><th>Việc làm</th><th>Chi tiết</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${new Date(x.createdAt).toLocaleString('vi-VN')}</td><td><b>${esc(auditLabel(x.action))}</b></td><td>${esc(x.description)}</td></tr>`).join(''):'<tr><td colspan="3" class="empty">Chưa có nhật ký.</td></tr>'}</tbody></table></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Đóng</button></div>`);$('modal').classList.add('history')}catch(e){toast(e.message,true)}}
function auditLabel(a){return ({PRODUCT_CREATE:'Thêm mặt hàng',PRODUCT_UPDATE:'Sửa mặt hàng',PRODUCT_DELETE:'Xóa mặt hàng',INVENTORY_IN:'Nhập hàng',INVENTORY_OUT:'Xuất hàng',TRANSACTION_UPDATE:'Sửa phiếu',TRANSACTION_DELETE:'Xóa phiếu',EXPENSE_CREATE:'Ghi chi phí',EXPENSE_UPDATE:'Sửa chi phí',EXPENSE_DELETE:'Xóa chi phí',STOCKTAKE:'Kiểm kê',EXCEL_SYNC:'Đồng bộ Excel',TRANSACTION_VOID:'Sửa sai phiếu',BACKUP_RESTORE:'Khôi phục backup',DRINK_DAILY_IMPORT:'Import Nước',DRINK_IMPORT_UNDO:'Hoàn tác import Nước'})[a]||a}
function forgotPassword(){openModal('Khôi phục mật khẩu',`<div class="note" style="margin-bottom:12px">Nhập mã khôi phục dạng <b>KHO-1234-5678</b> đã được cất khi cài phần mềm.</div><div class="form-grid"><div class="field full"><label>Mã khôi phục</label><input id="recoverCode" autocomplete="off" placeholder="KHO-0000-0000"></div><div class="field full"><label>Mật khẩu mới</label><input id="recoverPw" type="password"></div><div class="field full"><label>Nhập lại mật khẩu mới</label><input id="recoverPw2" type="password"></div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary" onclick="doRecoverPassword()">Đặt mật khẩu mới</button></div>`)}
async function doRecoverPassword(){const code=$('recoverCode').value.trim().toUpperCase(),pw=$('recoverPw').value;if(pw.length<minimumPasswordLength){toast('Mật khẩu mới cần ít nhất '+minimumPasswordLength+' ký tự.',true);return}if(pw!==$('recoverPw2').value){toast('Hai lần nhập mật khẩu chưa giống nhau.',true);return}try{const r=await fetch('/api/auth/recover',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({recoveryCode:code,newPassword:pw})});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.message||'Không khôi phục được mật khẩu');closeModal();toast('Đã đặt mật khẩu mới. Hãy đăng nhập lại.')}catch(e){toast(e.message,true)}}
function openRecoveryCode(){openModal('Tạo mã khôi phục mới',`<div class="note" style="margin-bottom:12px">Mã này dùng khi quên mật khẩu. Tạo mã mới sẽ làm mã cũ hết hiệu lực.</div><div class="field"><label>Nhập mật khẩu hiện tại</label><input id="recoveryCurrent" type="password"></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary" onclick="createRecoveryCode()">Tạo mã mới</button></div>`)}
async function createRecoveryCode(){try{const r=await api('/api/auth/recovery/create',{method:'POST',body:JSON.stringify({currentPassword:$('recoveryCurrent').value})});alert('MÃ KHÔI PHỤC MỚI\n\n'+r.recoveryCode+'\n\nHãy chụp ảnh hoặc ghi mã này ra giấy và cất riêng.');closeModal();toast('Đã tạo mã khôi phục mới')}catch(e){toast(e.message,true)}}
function openPassword(){openModal('Đổi mật khẩu',`<div class="form-grid"><div class="field full"><label>Mật khẩu đang dùng</label><input id="pwOld" type="password"></div><div class="field full"><label>Mật khẩu mới</label><input id="pwNew" type="password"><span class="hint">Ít nhất 6 ký tự.</span></div><div class="field full"><label>Nhập lại mật khẩu mới</label><input id="pwNew2" type="password"></div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary" onclick="changePassword()">Đổi mật khẩu</button></div>`)}
async function changePassword(){if($('pwNew').value.length<minimumPasswordLength){toast('Mật khẩu mới cần ít nhất '+minimumPasswordLength+' ký tự.',true);return}if($('pwNew').value!==$('pwNew2').value){toast('Hai lần nhập mật khẩu mới chưa giống nhau.',true);return}try{await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword:$('pwOld').value,newPassword:$('pwNew').value})});closeModal();toast('Đã đổi mật khẩu')}catch(e){toast(e.message,true)}}
function openHelp(){openModal('Hướng dẫn sử dụng',`<div class="help-steps"><div class="help-step"><b>1</b><div><b>Có loại hàng mới</b><br>Bấm “Thêm mặt hàng” hoặc trong “Nhập hàng” bấm “Hàng chưa có? Thêm mới”. Không cần mặt hàng đó có trong Excel.</div></div><div class="help-step"><b>2</b><div><b>Hàng được mua về</b><br>Bấm “Nhập hàng”, chọn tên hàng, ngày giờ phiếu và ghi số lượng. Có thể chọn ngày hôm qua nếu đang nhập bù phiếu.</div></div><div class="help-step"><b>3</b><div><b>Hàng được lấy ra</b><br>Bấm “Xuất hàng”, chọn tên hàng, ngày giờ phiếu và ghi số lượng. Có thể chọn ngày trước đó nếu cần.</div></div><div class="help-step"><b>4</b><div><b>Ghi nhầm</b><br>Vào “Sổ nhập xuất” → chọn “Sửa” để đổi số lượng hoặc “Xóa” để bỏ phiếu. Xóa phiếu xuất sẽ trả hàng lại kho; xóa phiếu nhập sẽ trừ hàng khỏi kho.</div></div><div class="help-step"><b>5</b><div><b>Xem một món đã nhập / xuất thế nào</b><br>Vào “Hàng trong kho” → bấm <b>Lịch sử</b> cạnh mặt hàng. Có thể lọc ngày, chỉ xem Nhập/Xuất và xuất riêng lịch sử món đó ra Excel.</div></div><div class="help-step"><b>6</b><div><b>Thấy “Sắp hết”</b><br>Vào “Kiểm kê & cần mua” để xem danh sách và xuất Excel đi mua.</div></div><div class="help-step"><b>7</b><div><b>Thỉnh thoảng kiểm kê</b><br>Đếm số ngoài kho rồi nhập vào “Kiểm kê”. Nếu lệch, phần mềm tự điều chỉnh và lưu lịch sử.</div></div><div class="help-step"><b>8</b><div><b>Sao lưu hoặc chuyển máy</b><br>Trong Cài đặt bấm “Xuất file chuyển máy”, rồi cất file ở USB, Google Drive hoặc OneDrive. Trên máy mới, tạo mật khẩu rồi bấm “Nhập file từ máy khác”.</div></div></div><div class="modal-actions"><button class="btn primary large" onclick="closeModal()">Đã hiểu</button></div>`)}

function showReportTab(tab){const map={quick:'reportQuick',custom:'reportCustom',ledger:'reportLedger'};Object.entries(map).forEach(([k,id])=>$(id)?.classList.toggle('hidden',k!==tab));[['quick','reportTabQuick'],['custom','reportTabCustom'],['ledger','reportTabLedger']].forEach(([k,id])=>$(id)?.classList.toggle('primary',k===tab))}
function setFontMode(mode){const m=mode==='large'?'large':'normal';document.body.dataset.fontSize=m;localStorage.setItem('kho-font-size',m);$('fontNormalBtn')?.classList.toggle('primary',m==='normal');$('fontLargeBtn')?.classList.toggle('primary',m==='large');toast(m==='large'?'Đã bật chữ lớn':'Đã dùng cỡ chữ bình thường')}
function applyFontMode(){const m=localStorage.getItem('kho-font-size')==='large'?'large':'normal';document.body.dataset.fontSize=m;setTimeout(()=>{$('fontNormalBtn')?.classList.toggle('primary',m==='normal');$('fontLargeBtn')?.classList.toggle('primary',m==='large')},0)}
function initVoiceSearch(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR)$('voiceSearchBtn')?.classList.remove('hidden')}
function startVoiceSearch(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Máy này chưa hỗ trợ tìm kiếm giọng nói.',true);return}const r=new SR();r.lang='vi-VN';r.interimResults=false;r.maxAlternatives=1;r.onresult=e=>{const q=e.results?.[0]?.[0]?.transcript||'';$('globalSearch').value=q;$('productSearch').value=q;showPage('products');renderProducts()};r.onerror=()=>toast('Không nghe rõ. Có thể gõ tên hàng như bình thường.',true);r.start()}

function showPage(id){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===id));$('pageTitle').textContent={dashboard:'Hôm nay',products:'Hàng trong kho',expenses:'Tiền đã chi',reports:'Báo cáo & sổ kho',operations:'Kiểm kê & cần mua',settings:'Cài đặt'}[id]||'Kho Nhà Mình';window.scrollTo({top:0,behavior:'smooth'})}
document.addEventListener('click',e=>{let b=e.target.closest('[data-page]');if(b)showPage(b.dataset.page)});$('productSearch').addEventListener('input',renderProducts);$('categoryFilter').addEventListener('change',renderProducts);$('stockFilter').addEventListener('change',renderProducts);$('globalSearch').addEventListener('input',e=>{$('productSearch').value=e.target.value;if(e.target.value){showPage('products');renderProducts()}});$('today').textContent=new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('reportDate').value=new Date().toISOString().slice(0,10);$('loginPassword').addEventListener('keydown',e=>{if(e.key==='Enter')login()});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('installBtn').classList.remove('hidden')});async function installApp(){if(!installPrompt){toast('Trên điện thoại, mở menu trình duyệt và chọn “Thêm vào màn hình chính”.');return}installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('installBtn').classList.add('hidden')}if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));applyFontMode();initVoiceSearch();showReportTab('quick');initAuth();
